const toolCallId = $('Code: Parse Booking Request').item.json.toolCallId;
const selectedStartTime = $('Code: Parse Booking Request').item.json.selectedStartTime;
let resultText;

if ($json.error) {
  resultText = "Couldn't confirm that slot automatically. Tell the caller a team member will call them back within the hour to lock in the time.";
} else {
  const when = new Date(selectedStartTime).toLocaleString('en-US', { weekday: 'long', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
  resultText = `Booked for ${when}. Read this exact time back to the caller to confirm, then end the call.`;
}

return { toolCallId, resultText };

const msg = $json.body?.message || {};
const call = msg.call || {};

let intake = null;
let bookingConfirmed = false;
let bookedTime = null;

try {
  const messages = msg.artifact?.messages || [];
  for (const m of messages) {
    const calls = m.toolCallList || m.toolCalls || (m.toolCallId ? [m] : []);
    for (const c of calls) {
      const name = c.function?.name || c.name;
      if (name === 'check_availability') {
        const argsRaw = c.function?.arguments || c.arguments;
        try {
          intake = typeof argsRaw === 'string' ? JSON.parse(argsRaw) : (argsRaw || intake);
        } catch (e) {
          // keep whatever intake already was
        }
      }
      if (name === 'book_appointment') {
        bookingConfirmed = true;
        const bookArgsRaw = c.function?.arguments || c.arguments;
        try {
          const bookArgs = typeof bookArgsRaw === 'string' ? JSON.parse(bookArgsRaw) : bookArgsRaw;
          bookedTime = bookArgs?.selectedStartTime || bookedTime;
        } catch (e) {
          // keep whatever bookedTime already was
        }
      }
    }
  }
} catch (e) {
  // fall through to defaults below
}

const durationSeconds = msg.durationSeconds || 0;
let callOutcome = 'Missed Call';
if (bookingConfirmed) callOutcome = 'Booked';
else if (intake) callOutcome = 'Intake Only - Callback Needed';

return {
  callerName: intake?.callerName || '',
  callerPhone: intake?.callerPhone || call.customer?.number || '',
  propertyAddress: intake?.propertyAddress || '',
  issueDescription: intake?.issueDescription || '',
  category: intake?.category || 'General',
  urgency: intake?.urgency || 'Routine',
  callOutcome,
  bookedTime: bookedTime || undefined,
  durationSeconds,
  isMissedCall: callOutcome === 'Missed Call'
};
